    top, bottom = min(rows), max(rows)
    left, right = min(cols), max(cols)

    # Output dimensions: input with 1 row/2 cols trimmed from each side
    output_h = len(grid) - 2
    output_w = len(grid[0]) - 2

    # Build output with background
    output = [[bg for _ in range(output_w)] for _ in range(output_h)]

    # Find corner marker value
    for r in range(top, min(top + 1, len(grid))):
        for c in range(left, right + 1):
            if grid[r][c] != bg:
                corners = [c for p in non_bg if p[0] == r and p[1] in (left, right)]
                if corners and all(grid[p[0]][p[1]] == corners[0] for p in corners):
                    marker = corners[0]
                    break
        else:
